// ==========================================
// Search Planner Interpreter
// Business Assistant V2.8 "Atlas"
// ==========================================

const raw = $json.output;

let plan;

try {
  plan = JSON.parse(raw);
} catch (error) {
  return [
    {
      json: {
        entity: "unknown",
        table: "unknown",
        filters: [],
        clarification: "invalid_json",
        company: null,
        limit: 50,
        sort: {
          field: "",
          direction: "desc"
        }
      }
    }
  ];
}

// Normalize entity names
const entityMap = {

  // Invoices
  invoice: "invoice",
  invoices: "invoice",
  Invoice: "invoice",
  Invoices: "invoice",

  // Receipts
  receipt: "receipt",
  receipts: "receipt",
  Receipt: "receipt",
  Receipts: "receipt",

  // Quotations
  quotation: "quotation",
  quotations: "quotation",
  quote: "quotation",
  quotes: "quotation",
  Quotation: "quotation",
  Quotations: "quotation",
  Quote: "quotation",
  Quotes: "quotation",

  // Transport Requests
  transport_request: "transport_request",
  transport_requests: "transport_request",
  "transport request": "transport_request",
  "transport requests": "transport_request",
  "Transport Request": "transport_request",
  "Transport Requests": "transport_request"
};

plan.entity = entityMap[plan.entity] || plan.entity;

// Normalize table names
const tableMap = {
  invoice: "invoices",
  receipt: "receipts",
  quotation: "quotations",
  transport_request: "transport_requests"
};

if (!plan.table || plan.table === "unknown") {
  plan.table = tableMap[plan.entity] || "unknown";
}

return [
  {
    json: {
      entity: plan.entity,
      table: plan.table,
      filters: plan.filters || [],
      clarification: plan.clarification || null,
      company: plan.company || null,
      limit: plan.limit || 50,
      sort: plan.sort || {
        field: "",
        direction: "desc"
      }
    }
  }
];

const input = $input.first().json;

const results = input.results || [];
const analytics = input.analytics || {};

const PAGE_SIZE = 20;
const SHOW_ALL_THRESHOLD = 20;

let displayedResults = results;
let shownResults = results.length;
let remainingResults = 0;

// Only paginate if there are more than 20 results
if (results.length > SHOW_ALL_THRESHOLD) {
  displayedResults = results.slice(0, PAGE_SIZE);
  shownResults = displayedResults.length;
  remainingResults = results.length - shownResults;
}

return [
  {
    json: {
      results: displayedResults,
      analytics,
      shownResults,
      totalResults: results.length,
      remainingResults
    }
  }
];

const rows = $input.all();

const entity = $('Search Planner Interpreter').first().json.entity || "unknown";

// ---------- Analytics ----------

const priorityCounts = {};
const statusCounts = {};

const supplierSet = new Set();
const vendorSet = new Set();
const companySet = new Set();
const customerSet = new Set();

let totalAmount = 0;
let amountCount = 0;

let totalWeight = 0;
let weightCount = 0;

for (const item of rows) {

  const row = item.json;

  // Priority
  if (row.priority) {
    priorityCounts[row.priority] =
      (priorityCounts[row.priority] || 0) + 1;
  }

  // Status
  if (row.status) {
    statusCounts[row.status] =
      (statusCounts[row.status] || 0) + 1;
  }

  // Supplier
  if (row.supplier) {
    supplierSet.add(row.supplier);
  }

  // Vendor
  if (row.vendor) {
    vendorSet.add(row.vendor);
  }

  // Company
  if (row.company) {
    companySet.add(row.company);
  }

  // Customer
  if (row.customer) {
    customerSet.add(row.customer);
  }

  // Amount
  if (row.amount) {

    const amount = parseFloat(row.amount);

    if (!isNaN(amount)) {
      totalAmount += amount;
      amountCount++;
    }

  }

  // Weight
  if (row.weight) {

    const weight = parseFloat(row.weight);

    if (!isNaN(weight)) {
      totalWeight += weight;
      weightCount++;
    }

  }

}

const analytics = {
  entity,
  totalResults: rows.length,

  priorityCounts,
  statusCounts,

  uniqueSuppliers: supplierSet.size,
  uniqueVendors: vendorSet.size,
  uniqueCompanies: companySet.size,
  uniqueCustomers: customerSet.size,

  totalAmount,
  averageAmount:
    amountCount > 0
      ? Number((totalAmount / amountCount).toFixed(2))
      : 0,

  totalWeight,
  averageWeight:
    weightCount > 0
      ? Number((totalWeight / weightCount).toFixed(2))
      : 0
};

return [
  {
    json: {
      results: rows.map(item => item.json),
      analytics
    }
  }
];

const plan = $('Search Planner Interpreter').item.json;

let sql = `
SELECT *
FROM invoices
`;

const whereClauses = [];

const numericFields = [
    'amount',
    'vat_amount'
];

const dateFields = [
    'invoice_date',
    'due_date'
];

for (const filter of plan.filters) {

    const isNumeric = numericFields.includes(filter.field);
    const isDate = dateFields.includes(filter.field);

    switch (filter.operator) {

        case 'contains':

            whereClauses.push(
                `${filter.field} ILIKE '%${filter.value}%'`
            );

            break;

        case 'equals':

            if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') = DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} = '${filter.value}'`
                );

            }

            break;

        case 'greater_than':

            if (isNumeric) {

                whereClauses.push(
                    `CAST(${filter.field} AS NUMERIC) > ${filter.value}`
                );

            } else if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') > DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} > '${filter.value}'`
                );

            }

            break;

        case 'less_than':

            if (isNumeric) {

                whereClauses.push(
                    `CAST(${filter.field} AS NUMERIC) < ${filter.value}`
                );

            } else if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') < DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} < '${filter.value}'`
                );

            }

            break;

        case 'greater_or_equal':

            if (isNumeric) {

                whereClauses.push(
                    `CAST(${filter.field} AS NUMERIC) >= ${filter.value}`
                );

            } else if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') >= DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} >= '${filter.value}'`
                );

            }

            break;

        case 'less_or_equal':

            if (isNumeric) {

                whereClauses.push(
                    `CAST(${filter.field} AS NUMERIC) <= ${filter.value}`
                );

            } else if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') <= DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} <= '${filter.value}'`
                );

            }

            break;
    }
}

if (whereClauses.length > 0) {

    sql += `
WHERE
${whereClauses.join('\nAND ')}
`;

}

sql += `
ORDER BY ${plan.sort.field} ${plan.sort.direction.toUpperCase()}
LIMIT ${plan.limit};
`;

// Extract supplier/company name from planner filters
const companyFilter = plan.filters.find(
    filter => filter.field === "supplier"
);

const company = companyFilter
    ? companyFilter.value
    : null;

return [
    {
        json: {
            query: sql,
            company,
            entity: "invoice"
        }
    }
];

